import { useCallback } from "react";

import { useLiveChannel, type LiveEvent } from "@/hooks/use-live-channel";
import { useToast } from "@/hooks/use-toast";

/**
 * Invisible listener mounted inside the authenticated shell. It holds the
 * app-wide connection to the backend's /ws/live channel and turns pushed
 * incident events (generated by the video/webcam inference pipeline) into
 * real-time toasts, so a violation detected in one workspace surfaces
 * everywhere in the product — not just on the page that triggered it.
 */
export function LiveAlerts() {
  const { toast } = useToast();

  const handleEvent = useCallback(
    (event: LiveEvent) => {
      if (event.type !== "incident_update") return;
      const payload = (event.payload ?? {}) as { missing_ppe?: string; severity?: string; label?: string; count?: number };
      const what = payload.missing_ppe || payload.label || "Safety violation";
      const detail = payload.severity
        ? `${payload.severity.toUpperCase()} · ${what}`
        : payload.count
          ? `${payload.count} × ${what}`
          : what;
      toast({ variant: "destructive", title: "New incident detected", description: detail });
    },
    [toast],
  );

  useLiveChannel(handleEvent);
  return null;
}
